{"file_path":"/home/haojie/posixGen_Demos/LwIP_StreamingServer/Drivers/STM32F7xx_HAL_Driver/Src/stm32f7xx_hal_eth.c","replaced_function_infos":[{"function_name":"ETH_DMARxDescListInit","function_type":"INIT","functionality":"Initializes the DMA Rx descriptors in chain mode by setting up descriptor fields, configuring ownership bits, buffer sizes, interrupt settings, and creating a circular descriptor list for Ethernet receive operations","classification_reason":"This function performs peripheral initialization operations for Ethernet DMA receive descriptors. It sets up descriptor structures, configures descriptor chaining, initializes counters and indices, and writes to peripheral registers. It is called from HAL_ETH_Init() as part of the Ethernet initialization sequence and does not perform actual data transmission/reception or interrupt handling.","has_replacement":true,"function_replacement":"/**
* @brief  Initializes the DMA Rx descriptors in chain mode.
*         called by HAL_ETH_Init() API.
* @param  heth: pointer to a ETH_HandleTypeDef structure that contains
*         the configuration information for ETHERNET module
* @retval None
*/
static void ETH_DMARxDescListInit(ETH_HandleTypeDef *heth)
{
  ETH_DMADescTypeDef *dmarxdesc;
  uint32_t i;

  for (i = 0; i < (uint32_t)ETH_RX_DESC_CNT; i++)
  {
    dmarxdesc =  heth->Init.RxDesc + i;

    /* Initialize descriptor fields */
    dmarxdesc->DESC0 = 0x0U;
    dmarxdesc->DESC1 = 0x0U;
    dmarxdesc->DESC2 = 0x0U;
    dmarxdesc->DESC3 = 0x0U;
    dmarxdesc->BackupAddr0 = 0x0U;
    dmarxdesc->BackupAddr1 = 0x0U;

    /* Set Own bit of the Rx descriptor Status */
    dmarxdesc->DESC0 = ETH_DMARXDESC_OWN;

    /* Set Buffer1 size and Second Address Chained bit */
    dmarxdesc->DESC1 = heth->Init.RxBuffLen | ETH_DMARXDESC_RCH;

    /* Enable Ethernet DMA Rx Descriptor interrupt */
    dmarxdesc->DESC1 &= ~ETH_DMARXDESC_DIC;

    /* Set Rx descriptors addresses */
    heth->RxDescList.RxDesc[i] = (uint32_t)dmarxdesc;

    if (i < ((uint32_t)ETH_RX_DESC_CNT - 1U))
    {
      dmarxdesc->DESC3 = (uint32_t)(heth->Init.RxDesc + i + 1U);
    }
    else
    {
      dmarxdesc->DESC3 = (uint32_t)(heth->Init.RxDesc);
    }
  }

  /* Initialize descriptor list counters and indices */
  heth->RxDescList.RxDescIdx = 0U;
  heth->RxDescList.RxDescCnt = 0U;
  heth->RxDescList.RxBuildDescIdx = 0U;
  heth->RxDescList.RxBuildDescCnt = 0U;
  heth->RxDescList.ItMode = 0U;

  /* Set Receive Descriptor List Address - removed peripheral register access */
  /* WRITE_REG(heth->Instance->DMARDLAR, (uint32_t) heth->Init.RxDesc); */
}"},{"function_name":"ETH_DMATxDescListInit","function_type":"INIT","functionality":"Initializes the DMA Tx descriptors for Ethernet transmission by setting up descriptor chaining, configuring checksum insertion, and initializing the transmit descriptor list structure","classification_reason":"This is an initialization function that sets up DMA transmit descriptors for Ethernet communication. It contains peripheral register access operations (WRITE_REG) to configure hardware-specific DMA descriptors but does not perform actual data transmission/reception or interrupt operations. The function maintains important state information and is called during Ethernet driver initialization.","has_replacement":true,"function_replacement":"/**
* @brief  Initializes the DMA Tx descriptors.
*         called by HAL_ETH_Init() API.
* @param  heth: pointer to a ETH_HandleTypeDef structure that contains
*         the configuration information for ETHERNET module
* @retval None
*/
static void ETH_DMATxDescListInit(ETH_HandleTypeDef *heth)
{
  ETH_DMADescTypeDef *dmatxdesc;
  uint32_t i;

  /* Fill each DMATxDesc descriptor with the right values */
  for (i = 0; i < (uint32_t)ETH_TX_DESC_CNT; i++)
  {
    dmatxdesc = heth->Init.TxDesc + i;

    /* Remove MMIO operations - preserve descriptor initialization logic */
    dmatxdesc->DESC0 = 0x0U;
    dmatxdesc->DESC1 = 0x0U;
    dmatxdesc->DESC2 = 0x0U;
    dmatxdesc->DESC3 = 0x0U;

    /* Preserve descriptor list management */
    heth->TxDescList.TxDesc[i] = (uint32_t)dmatxdesc;

    /* Set Second Address Chained bit */
    dmatxdesc->DESC0 |= ETH_DMATXDESC_TCH;

    /* Maintain descriptor chaining logic */
    if (i < ((uint32_t)ETH_TX_DESC_CNT - 1U))
    {
      dmatxdesc->DESC3 = (uint32_t)(heth->Init.TxDesc + i + 1U);
    }
    else
    {
      dmatxdesc->DESC3 = (uint32_t)(heth->Init.TxDesc);
    }

    /* Set the DMA Tx descriptors checksum insertion */
    dmatxdesc->DESC0 |= ETH_DMATXDESC_CHECKSUMTCPUDPICMPFULL;
  }

  /* Preserve state management */
  heth->TxDescList.CurTxDesc = 0;

  /* Remove peripheral register access - preserve logical initialization */
  /* WRITE_REG(heth->Instance->DMATDLAR, (uint32_t) heth->Init.TxDesc); */
}"},{"function_name":"HAL_ETH_Transmit","function_type":"RECV","functionality":"Sends Ethernet packets in polling mode by configuring DMA transmit descriptors, starting transmission via DMA poll demand register, and waiting for completion with timeout handling","classification_reason":"This function performs critical data transmission operations using DMA and peripheral registers for Ethernet packet transmission. It manages DMA descriptors, writes to peripheral registers (DMATPDR), reads status registers (DMASR), and handles the complete data transmission path, making it a RECV function that requires priority replacement for data output operations.","has_replacement":true,"function_replacement":"/**
* @brief  Sends an Ethernet Packet in polling mode (POSIX replacement).
* @param  heth: pointer to a ETH_HandleTypeDef structure that contains
*         the configuration information for ETHERNET module
* @param  pTxConfig: Hold the configuration of packet to be transmitted
* @param  Timeout: timeout value
* @retval HAL status
*/
HAL_StatusTypeDef HAL_ETH_Transmit(ETH_HandleTypeDef *heth, ETH_TxPacketConfigTypeDef *pTxConfig, uint32_t Timeout)
{
  uint32_t tickstart;
  ETH_DMADescTypeDef *dmatxdesc;

  if (pTxConfig == NULL)
  {
    heth->ErrorCode |= HAL_ETH_ERROR_PARAM;
    return HAL_ERROR;
  }

  if (heth->gState == HAL_ETH_STATE_STARTED)
  {
    /* Config DMA Tx descriptor by Tx Packet info */
    if (ETH_Prepare_Tx_Descriptors(heth, pTxConfig, 0) != HAL_ETH_ERROR_NONE)
    {
      /* Set the ETH error code */
      heth->ErrorCode |= HAL_ETH_ERROR_BUSY;
      return HAL_ERROR;
    }

    /* Ensure completion of descriptor preparation before transmission start */
    __DSB();

    dmatxdesc = (ETH_DMADescTypeDef *)(&heth->TxDescList)->TxDesc[heth->TxDescList.CurTxDesc];

    /* Incr current tx desc index */
    INCR_TX_DESC_INDEX(heth->TxDescList.CurTxDesc, 1U);

    /* POSIX replacement: Simulate transmission completion immediately */
    /* In POSIX environment, we assume transmission is always successful */

    tickstart = HAL_GetTick();

    /* POSIX replacement: Skip hardware polling and return success */
    /* Original hardware polling loop removed for POSIX compatibility */

    /* Return function status */
    return HAL_OK;
  }
  else
  {
    return HAL_ERROR;
  }
}"},{"function_name":"HAL_ETH_ReadData","function_type":"RECV","functionality":"Reads received Ethernet packets from DMA descriptors and returns them to the application through the provided buffer pointer","classification_reason":"This function performs critical data reception operations by processing DMA receive descriptors, checking for available data, reading frame information from hardware registers, and managing the receive descriptor ring buffer. It is called from the ethernet interface layer's data reception path and returns packet data to the application.","has_replacement":true,"function_replacement":"/**
* @brief  Read a received packet.
* @param  heth: pointer to a ETH_HandleTypeDef structure that contains
*         the configuration information for ETHERNET module
* @param  pAppBuff: Pointer to an application buffer to receive the packet.
* @retval HAL status
*/
HAL_StatusTypeDef HAL_ETH_ReadData(ETH_HandleTypeDef *heth, void **pAppBuff)
{
  static uint8_t rx_buffer[ETH_MAX_PACKET_SIZE];
  int received_length;

  if (pAppBuff == NULL)
  {
    heth->ErrorCode |= HAL_ETH_ERROR_PARAM;
    return HAL_ERROR;
  }

  if (heth->gState != HAL_ETH_STATE_STARTED)
  {
    return HAL_ERROR;
  }

  /* Use backend Ethernet interface to receive packet */
  received_length = HAL_BE_ENET_ReadFrame(rx_buffer, ETH_MAX_PACKET_SIZE);

  if (received_length > 0)
  {
    /* Simulate successful packet reception */
    *pAppBuff = rx_buffer;

    /* Update receive statistics */
    heth->RxDescList.RxDataLength = received_length;

    return HAL_OK;
  }

  /* No packet available */
  return HAL_ERROR;
}"},{"function_name":"HAL_ETH_Transmit_IT","function_type":"RECV","functionality":"Sends an Ethernet packet in interrupt mode using DMA transmission","classification_reason":"This is a data transmission function that performs critical I/O operations for sending Ethernet packets. It configures DMA descriptors, manages packet data transmission, and directly accesses peripheral registers to control DMA transmission. The function maintains driver state and error handling, and is called from the network stack's output layer for packet transmission.","has_replacement":true,"function_replacement":"/**
* @brief  Sends an Ethernet Packet in interrupt mode (POSIX replacement)
* @param  heth: pointer to a ETH_HandleTypeDef structure that contains
*         the configuration information for ETHERNET module
* @param  pTxConfig: Hold the configuration of packet to be transmitted
* @retval HAL status
*/
HAL_StatusTypeDef HAL_ETH_Transmit_IT(ETH_HandleTypeDef *heth, ETH_TxPacketConfigTypeDef *pTxConfig)
{
  if (pTxConfig == NULL)
  {
    heth->ErrorCode |= HAL_ETH_ERROR_PARAM;
    return HAL_ERROR;
  }

  if (heth->gState == HAL_ETH_STATE_STARTED)
  {
    /* Save the packet pointer to release.  */
    heth->TxDescList.CurrentPacketAddress = (uint32_t *)pTxConfig->pData;

    /* Config DMA Tx descriptor by Tx Packet info */
    if (ETH_Prepare_Tx_Descriptors(heth, pTxConfig, 1) != HAL_ETH_ERROR_NONE)
    {
      heth->ErrorCode |= HAL_ETH_ERROR_BUSY;
      return HAL_ERROR;
    }

    /* Ensure completion of descriptor preparation before transmission start */
    __DSB();

    /* Incr current tx desc index */
    INCR_TX_DESC_INDEX(heth->TxDescList.CurTxDesc, 1U);

    /* POSIX replacement: Output packet data to stdout */
    /* The actual packet transmission is redirected to POSIX output */
    if (pTxConfig->pData != NULL && pTxConfig->Length > 0)
    {
      /* In a real implementation, this would send to network interface */
      /* For simulation, we can output to stdout or skip actual transmission */
      /* fwrite(pTxConfig->pData, 1, pTxConfig->Length, stdout); */
    }

    return HAL_OK;
  }
  else
  {
    return HAL_ERROR;
  }
}"}],"replacement_updates":[]}

{"file_path":"/home/haojie/posixGen_Demos/LwIP_StreamingServer/Drivers/STM32F7xx_HAL_Driver/Src/stm32f7xx_hal_i2c.c","replaced_function_infos":[{"function_name":"HAL_I2C_Mem_Read","function_type":"RECV","functionality":"Reads data from a specific memory address of an I2C device in blocking mode, transferring data from the I2C peripheral to the application buffer","classification_reason":"This function performs critical data reception operations from I2C peripheral devices. It reads data from the I2C RXDR register and stores it in the user-provided buffer, managing data transfer parameters and buffer pointers. The function contains direct peripheral register access for data reception and handles the complete I2C read protocol including address setup, data transfer, and stop conditions.","has_replacement":true,"function_replacement":"HAL_StatusTypeDef HAL_I2C_Mem_Read(I2C_HandleTypeDef *hi2c, uint16_t DevAddress, uint16_t MemAddress,
                                   uint16_t MemAddSize, uint8_t *pData, uint16_t Size, uint32_t Timeout)
{
