  assert_param(IS_I2C_MEMADD_SIZE(MemAddSize));

  if (hi2c->State == HAL_I2C_STATE_READY)
  {
    if ((pData == NULL) || (Size == 0U))
    {
      hi2c->ErrorCode = HAL_I2C_ERROR_INVALID_PARAM;
      return HAL_ERROR;
    }

    /* Process Locked */
    __HAL_LOCK(hi2c);

    hi2c->State     = HAL_I2C_STATE_BUSY_RX;
    hi2c->Mode      = HAL_I2C_MODE_MEM;
    hi2c->ErrorCode = HAL_I2C_ERROR_NONE;

    /* Prepare transfer parameters */
    hi2c->pBuffPtr  = pData;
    hi2c->XferCount = Size;
    hi2c->XferISR   = NULL;

    /* Use HAL_BE_In to simulate I2C data reception */
    int bytes_read = HAL_BE_In(pData, Size);

    if (bytes_read < 0)
    {
      /* Process Unlocked */
      __HAL_UNLOCK(hi2c);
      hi2c->State = HAL_I2C_STATE_READY;
      hi2c->Mode  = HAL_I2C_MODE_NONE;
      return HAL_ERROR;
    }

    /* Update transfer counters based on actual bytes read */
    hi2c->XferCount = bytes_read;
    hi2c->XferSize = bytes_read;

    hi2c->State = HAL_I2C_STATE_READY;
    hi2c->Mode  = HAL_I2C_MODE_NONE;

    /* Process Unlocked */
    __HAL_UNLOCK(hi2c);

    return HAL_OK;
  }
  else
  {
    return HAL_BUSY;
  }
}"},{"function_name":"HAL_I2C_Slave_Receive","function_type":"RECV","functionality":"I2C slave mode data reception in blocking mode - receives specified amount of data from I2C peripheral into user buffer","classification_reason":"This function performs critical data reception operations by reading from I2C peripheral registers (RXDR) into user-provided buffer. It implements complete I2C slave receive protocol including address matching, data reception, and stop condition handling. The core operation involves direct peripheral register access for data transfer, making it a priority RECV candidate.","has_replacement":true,"function_replacement":"/**
* @brief  Receive in slave mode an amount of data in blocking mode
* @param  hi2c Pointer to a I2C_HandleTypeDef structure that contains
*                the configuration information for the specified I2C.
* @param  pData Pointer to data buffer
* @param  Size Amount of data to be sent
* @param  Timeout Timeout duration
* @retval HAL status
*/
HAL_StatusTypeDef HAL_I2C_Slave_Receive(I2C_HandleTypeDef *hi2c, uint8_t *pData, uint16_t Size,
                                        uint32_t Timeout)
{
  uint32_t tickstart;

  if (hi2c->State == HAL_I2C_STATE_READY)
  {
    if ((pData == NULL) || (Size == 0U))
    {
      hi2c->ErrorCode = HAL_I2C_ERROR_INVALID_PARAM;
      return  HAL_ERROR;
    }
    /* Process Locked */
    __HAL_LOCK(hi2c);

    /* Init tickstart for timeout management*/
    tickstart = HAL_GetTick();

    hi2c->State     = HAL_I2C_STATE_BUSY_RX;
    hi2c->Mode      = HAL_I2C_MODE_SLAVE;
    hi2c->ErrorCode = HAL_I2C_ERROR_NONE;

    /* Prepare transfer parameters */
    hi2c->pBuffPtr  = pData;
    hi2c->XferCount = Size;
    hi2c->XferSize = hi2c->XferCount;
    hi2c->XferISR   = NULL;

    /* Use HAL_BE_In to simulate receiving data from I2C */
    int received_bytes = HAL_BE_In(pData, Size);

    if (received_bytes < 0)
    {
      /* Error in receiving data */
      hi2c->ErrorCode = HAL_I2C_ERROR_TIMEOUT;
      hi2c->State = HAL_I2C_STATE_READY;
      hi2c->Mode  = HAL_I2C_MODE_NONE;
      __HAL_UNLOCK(hi2c);
      return HAL_ERROR;
    }

    /* Update transfer counters based on actual received bytes */
    hi2c->XferCount = Size - received_bytes;
    hi2c->XferSize = hi2c->XferCount;

    /* Update buffer pointer */
    hi2c->pBuffPtr += received_bytes;

    hi2c->State = HAL_I2C_STATE_READY;
    hi2c->Mode  = HAL_I2C_MODE_NONE;

    /* Process Unlocked */
    __HAL_UNLOCK(hi2c);

    return HAL_OK;
  }
  else
  {
    return HAL_BUSY;
  }
}"},{"function_name":"HAL_I2C_Master_Receive","function_type":"RECV","functionality":"I2C master mode data reception in blocking mode - receives data from I2C peripheral device and stores it in buffer","classification_reason":"This function performs critical data I/O operations by reading data from I2C peripheral's RXDR register and storing it in the provided buffer. It manages data buffer pointers and transfer counters, handles I2C communication protocol including slave addressing and flag waiting, and maintains the I2C state machine. The core operation is data reception from peripheral hardware.","has_replacement":true,"function_replacement":"/**
